import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"FR 3.4.13 — View Workspace Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/03-agency-workspace/3-4-13-view-workspace-dashboard/spec.md","filePath":"feature/srs/03-agency-workspace/3-4-13-view-workspace-dashboard/spec.md"}'),s={name:"feature/srs/03-agency-workspace/3-4-13-view-workspace-dashboard/spec.md"};function n(c,e,d,i,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-4-13-—-view-workspace-dashboard" tabindex="-1">FR 3.4.13 — View Workspace Dashboard <a class="header-anchor" href="#fr-3-4-13-—-view-workspace-dashboard" aria-label="Permalink to &quot;FR 3.4.13 — View Workspace Dashboard&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.4.13</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-026</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View Workspace Dashboard</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Agency &amp; Workspace (<code>FR 3.4</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-15, BR-20</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-scope" tabindex="-1">1. Objective &amp; Scope <a class="header-anchor" href="#_1-objective-scope" aria-label="Permalink to &quot;1. Objective &amp; Scope&quot;">​</a></h2><p>Xem bảng điều khiển tổng quan của từng Workspace (Workspace Dashboard — /workspaces/:id/dashboard). Hiển thị thống kê tiến độ công việc theo trạng thái (Backlog, In Progress, In Review, Approved, Published), lịch đăng bài sắp tới, tiến độ chiến dịch truyền thông và lượng AI Credit đã sử dụng của Workspace.</p><p><strong>Implementation Summary:</strong> Combines Workspace summary metadata (<code>GET /workspaces/{workspaceId}/dashboard</code>) with the 2-tab Role-Based Workspace Dashboard (<code>Overview</code> + <code>Analytics</code> via <code>/api/v1/analytics/workspaces/{workspaceId}/*</code>), tailoring KPIs, Next-Up cards, attention alerts, and drill-down task/post drawers to <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, and <code>Client</code>.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner, Manager, Creator, Client</code>), I want to execute <strong>View Workspace Dashboard</strong> with strict multi-tenant authorization and real-time state consistency, so that organizational governance and role-scoped workflows satisfy <code>BR-15, BR-20</code> across Web and Mobile.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Gate:</strong> Only authenticated users holding <code>Owner, Manager, Creator, Client</code> within the target Agency/Workspace scope may invoke <code>GET /api/v1/workspaces/{workspaceId}/dashboard · GET /api/v1/analytics/workspaces/{workspaceId}[/overview|/items]</code>; unauthorized callers are rejected (<code>401</code> / <code>403</code>).</li><li><strong>Business Rule Enforcement (<code>BR-15, BR-20</code>):</strong> Backend service logic (<code>WorkspaceServiceImpl.getDashboard(), DashboardAnalyticsService</code>) enforces all domain invariants, uniqueness constraints, and soft-delete / single-Manager / TTL rules before committing state changes.</li><li><strong>Standardized Envelope &amp; Persistence:</strong> Reads and mutations against PostgreSQL <code>workspaces</code>, <code>workspace_members</code>, <code>workspace_media_packages</code>, <code>media_campaigns</code>; MongoDB <code>tasks</code>, <code>posts</code> return <code>ApiResponse&lt;T&gt;</code> with deterministic <code>ErrorCode</code> mappings (<code>403 WORKSPACE_ACCESS_DENIED</code> / <code>FORBIDDEN</code>, <code>404 WORKSPACE_NOT_FOUND</code>) and <code>X-Request-Id</code> correlation.</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> All UI labels, empty states, dialogs, and toast notifications use parallel locale keys (<code>workspace.dashboard.* / dashboard.*</code>) in <code>vi</code> and <code>en</code> bundles — zero hardcoded strings in JSX/TSX.</li><li><strong>Semantic Light/Dark Theme:</strong> All cards, tables, badges, drawers, and confirmation modals use semantic CSS variables / Tailwind <code>dark:</code> tokens (<code>brandhub-web</code>) and <code>useTheme()</code> tokens (<code>brandhub-mobile-app</code>) with WCAG-compliant contrast.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/workspace/dashboard.tsx</code>, <code>src/pages/workspace/components/dashboard/{WorkspaceDashboardHeader,DashboardTabSwitcher,RoleWorkspaceOverview,WorkspaceAnalyticsTab}.tsx</code>, <code>src/components/dashboard/{DetailDrawer,AttentionStrip,NextUpCard}.tsx</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/workspace/WorkspaceDetailScreen.tsx</code>, <code>src/screens/dashboard/DashboardScreen.tsx</code>, <code>src/services/dashboardAnalyticsService.ts</code></li><li><strong>Interactive States:</strong><ul><li><strong>Loading:</strong> Skeleton cards/rows and disabled in-flight submit buttons preventing duplicate requests.</li><li><strong>Empty State:</strong> Contextual empty state with localized guidance and primary CTA where permitted by role.</li><li><strong>Success:</strong> TanStack Query cache invalidation + localized confirmation toast without full-page reload.</li><li><strong>Error / Recovery:</strong> Inline field validation or retryable <code>DataErrorState</code> banner mapped from backend <code>ErrorCode</code> — never silently falling back to mock data.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><ul><li><strong>Endpoints:</strong> <code>GET /api/v1/workspaces/{workspaceId}/dashboard · GET /api/v1/analytics/workspaces/{workspaceId}[/overview|/items]</code></li><li><strong>Controller &amp; Service (<code>brandhub-business-service</code>):</strong> <code>WorkspaceController.getDashboard(), DashboardAnalyticsController.workspace() / workspaceOverview() / workspaceItems()</code> -&gt; <code>WorkspaceServiceImpl.getDashboard(), DashboardAnalyticsService</code></li><li><strong>Repositories &amp; Stores:</strong> WorkspaceRepository, WorkspaceMemberRepository, WorkspaceMediaPackageRepository, MediaCampaignRepository, TaskMongoRepository, PostMongoRepository, CreditAccountingStore</li><li><strong>Authentication:</strong> <code>Authorization: Bearer &lt;accessToken&gt;</code> verified by <code>JwtAuthFilterGatewayFilterFactory</code> (<code>brandhub-api-gateway</code>) and <code>JwtAuthenticationFilter</code> / <code>@RequireRoleAspect</code> (<code>brandhub-business-service</code>).</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Error Codes:</strong> <code>403 WORKSPACE_ACCESS_DENIED</code> / <code>FORBIDDEN</code>, <code>404 WORKSPACE_NOT_FOUND</code>.</li><li><strong>Tenant Boundary Isolation:</strong> Soft-deleted Agencies/Workspaces (<code>EntityStatus.SOFT_DELETED</code>) and deactivated memberships (<code>is_active = false</code>) are excluded from operational reads and rejected on mutations.</li><li><strong>Concurrency &amp; Idempotency:</strong> Transactional persistence (<code>@Transactional</code>) and database unique constraints prevent duplicate memberships, duplicate active Managers, or partial writes under concurrent requests.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend endpoints and service logic verified against <a href="./test.html">test.md</a>, Web &amp; Mobile UI wired to live APIs, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark mode verified.</li><li><strong>Out of Scope:</strong> Adjacent Agency/Workspace operations covered by sibling FRs in <code>3.4.1–3.4.26</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/03-agency-workspace.html">BA Agency &amp; Workspace Spec</a> · <a href="./../../../../ba/01-organization-structure.html">Organization Structure</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const u=a(s,[["render",n]]);export{h as __pageData,u as default};
